41	const PROCESSING_FEE = 5;
42	
43	const FIRST_INSURANCE_PERCENT = 10;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const BLOCK_SIZE = 3;
55	const BLOCK_BASE_PREMIUM = 60;
56	
57	const countByType = (items: Item[]): Map<string, number> => {
58	  const counts = new Map<string, number>();
59	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
60	
61	  return counts;
62	};
63	
64	const basePremiumForType = (type: string, count: number): number =>
65	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
66	
67	const policyBasePremium = (items: Item[]): number =>
68	  [...countByType(items)]
69	    .map(([type, count]) => basePremiumForType(type, count))
70	    .reduce((total, premium) => total + premium, 0);
71	
72	const CURSE_PERCENT = 50;
73	
74	// Percentages MUST go through this helper. Multiplying first and dividing by
75	// 100 afterwards keeps the arithmetic drift-free; the tempting `amount * 0.5`
76	// (or `* 1.1`) introduces binary-fraction error — 100 * 1.1 yields
77	// 110.00000000000001 — and since the spec rounds premiums UP at the very end
78	// that drift becomes a whole extra G.
79	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
80	
81	const HIGH_ENCHANTMENT_PERCENT = 30;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	
84	const surchargeFor = (item: Item): number => {
85	  const base = BASE_PREMIUMS[item.type];
86	  const curse = item.cursed ? percentOf(base, CURSE_PERCENT) : 0;
87	  const enchantment =
88	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
89	      ? percentOf(base, HIGH_ENCHANTMENT_PERCENT)
90	      : 0;
91	
92	  return curse + enchantment;
93	};
94	
95	const itemSurcharges = (items: Item[]): number =>
96	  items.reduce((total, item) => total + surchargeFor(item), 0);
97	
98	// Every modifier is a percentage of a base premium, and they are SUMMED rather
99	// than compounded: the spec's worked example reads
100	// "100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G",
101	// so the first-insurance 10 % is taken on the policy base, not on the
102	// curse-inflated amount.
103	const quote = ({ items }: QuoteStep): StepResult => {
104	  const policyBase = policyBasePremium(items);
105	  const firstInsurance = percentOf(policyBase, FIRST_INSURANCE_PERCENT);
106	  const total = policyBase + itemSurcharges(items) + firstInsurance + PROCESSING_FEE;
107	
108	  return { premium: Math.ceil(total) };
109	};
110	
111	export const runScenario = (scenario: Scenario): ScenarioResult => ({
112	  // Only quote steps are exercised so far; claim dispatch arrives with its first test.
113	  results: scenario.steps.map((step) => quote(step as QuoteStep)),
114	});
